export class AccountClient {
  constructor({fetcher=(...args)=>fetch(...args),onChange=()=>{},onError=()=>{},clock=()=>Date.now(),setTimer=(...args)=>setTimeout(...args),clearTimer=id=>clearTimeout(id)}={}){Object.assign(this,{fetcher,onChange,onError,clock,setTimer,clearTimer});this.user=null;this.csrf=null;this.generation=0;this.auto=false;this.bound=null;this.timer=null;this.pending=null;this.busy=false;this.lastAttempt=0;this.syncText='本机存档';}
  async request(path,method='GET',data){const control=new AbortController(),timeout=this.setTimer(()=>control.abort(),15000);try{const response=await this.fetcher('/api/player/'+path,{method,credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json','X-Qingyun-Client':'web-v1',...(this.csrf?{'X-Qingyun-CSRF':this.csrf}:{})},...(data===undefined?{}:{body:JSON.stringify(data)}),signal:control.signal});let body;try{body=await response.json();}catch{throw Error('当前入口暂时无法连接云账户，请使用正式游戏网址或稍后重试。');}if(!response.ok){const e=Error(body.error||'账户操作未完成');e.status=response.status;e.currentRevision=body.currentRevision;throw e;}return body;}finally{this.clearTimer(timeout);}}
  pause(){this.auto=false;this.pending=null;if(this.timer)this.clearTimer(this.timer);this.timer=null;this.syncText=this.user?'自动云存档未开启':'本机存档';this.onChange();}
  replaceSession(data){this.generation++;this.pause();this.user=data?.user||null;this.csrf=data?.csrf||null;this.bound=null;this.syncText=this.user?'已登录 · 自动云存档未开启':'本机存档';this.onChange();}
  async refresh(){const gen=this.generation;const data=await this.request('me');if(gen===this.generation)this.replaceSession(data);return this.user;}
  async auth(action,data){const result=await this.request(action,'POST',data);this.replaceSession(result);return result;}
  async logout(all=false){this.pause();await this.request(all?'logout-all':'logout','POST',{});this.replaceSession(null);}
  async slots(){return (await this.request('saves')).slots;}
  async download(slot,revision){return this.request(`saves/${slot}${revision===undefined?'':'/versions/'+revision}`);}
  async versions(slot){return (await this.request(`saves/${slot}/versions`)).versions;}
  bind(slot,revision,label='自动存档'){this.pause();this.bound={slot,revision,label};this.onChange();}
  async upload(slot,revision,data,label){const gen=this.generation,result=await this.request('saves/'+slot,'PUT',{baseRevision:revision,data,label});if(gen!==this.generation)throw Error('账户状态已变化，请重新查看存档。');return result;}
  setAuto(enabled){if(enabled&&(!this.user||!this.bound))throw Error('请先上传或载入一个云存档槽。');this.auto=!!enabled;this.syncText=this.auto?'自动云存档已开启':'自动云存档未开启';if(!enabled)this.pause();else this.onChange();}
  schedule(data){if(!this.auto||!this.user||!this.bound||!data)return;this.pending=JSON.stringify(data);this.syncText='等待同步 · 本机已保存';this.onChange();if(this.timer)this.clearTimer(this.timer);this.timer=this.setTimer(()=>{this.timer=null;this.flush();},Math.max(1800,this.lastAttempt+15000-this.clock()));}
  async flush(){if(this.busy||!this.pending||!this.auto||!this.bound)return;this.busy=true;const snapshot=this.pending,gen=this.generation,bound={...this.bound};this.lastAttempt=this.clock();try{const result=await this.upload(bound.slot,bound.revision,JSON.parse(snapshot),bound.label);if(gen===this.generation&&this.auto&&this.bound?.slot===bound.slot){this.bound.revision=result.revision;if(this.pending===snapshot)this.pending=null;this.syncText='云端已同步 · 版本'+result.revision;this.onChange();}}catch(e){if(gen===this.generation){this.pause();this.syncText='云同步暂停 · 本机已保存';this.onChange();this.onError(e.message);}}finally{this.busy=false;if(this.pending&&this.auto){if(this.timer)this.clearTimer(this.timer);this.timer=this.setTimer(()=>{this.timer=null;this.flush();},Math.max(1800,this.lastAttempt+15000-this.clock()));}}}
}
